:root{--paper:#F6F8FB;--white:#fff;--ink:#0E1A2B;--accent:#2F6FED;--accent-d:#2459D0;--sky:#E3ECFD;--oak:#EFE7DA; --ink-2:rgba(14,26,43,.72);--ink-3:rgba(14,26,43,.14); --sans:"Satoshi",ui-sans-serif,system-ui,sans-serif;--serif:"Fraunces",Georgia,serif; --r-s:12px;--r-m:22px;--r-l:36px; --ease:cubic-bezier(.16,1,.3,1); --gut:clamp(20px,4.4vw,64px);--max:1280px;}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%;scroll-padding-top:90px}
