html{scrollbar-color:#b9c6dc var(--paper)}
h1,h2,h3{margin:0;font-weight:450;text-wrap:balance}
.wrap{width:100%;max-width:calc(var(--max) + var(--gut)*2);margin:0 auto;padding:0 var(--gut)}
.h1{font-family:var(--serif);font-size:clamp(44px,6.2vw,92px);line-height:1.02;letter-spacing:-.03em;font-variation-settings:"opsz" 144}
.h2{font-family:var(--serif);font-size:clamp(34px,4.3vw,62px);line-height:1.06;letter-spacing:-.025em;font-variation-settings:"opsz" 144;max-width:16ch}
.lead{font-size:clamp(18px,1.4vw,20px);color:var(--ink-2);max-width:46ch;line-height:1.55}
.btn{--bg:var(--ink);--fg:#fff;display:inline-flex;align-items:center;gap:10px;min-height:52px;padding:0 24px;border-radius:999px;border:1.5px solid var(--bg);background:var(--bg);color:var(--fg);font:500 16px/1 var(--sans);text-decoration:none;cursor:pointer;transition:transform .35s var(--ease),background-color .3s,color .3s,box-shadow .35s var(--ease)}
.btn:hover{transform:translateY(-2px);box-shadow:0 10px 24px -12px rgba(47,111,237,.55)}
.btn:hover svg{transform:translateX(3px)}
.btn:active{transform:translateY(0) scale(.98)}
.btn--solid{--bg:var(--accent)}
.btn--solid:hover{--bg:var(--accent-d)}
.btn--line{--bg:transparent;--fg:var(--ink);border-color:var(--ink-3)}
.btn--line:hover{border-color:var(--ink);box-shadow:none}
.btn--white{--bg:#fff;--fg:var(--ink)}
.btn--sm{min-height:42px;padding:0 18px;font-size:15px}
.hero{padding:clamp(28px,4vw,56px) 0 clamp(48px,6vw,88px);min-height:calc(100svh - 120px);display:flex;align-items:center}
.hero__in{display:grid;grid-template-columns:1.05fr .95fr;gap:clamp(32px,5vw,80px);align-items:center}
.hero__cta{display:flex;gap:12px;flex-wrap:wrap;margin-top:36px}
.hero__facts{list-style:none;padding:28px 0 0;margin:44px 0 0;border-top:1px solid var(--ink-3);display:flex;gap:clamp(18px,3vw,44px);font-size:14px;color:var(--ink-2);flex-wrap:wrap}
.hero__art{position:relative;aspect-ratio:4/4.6;max-width:560px;width:100%;justify-self:end}
.hero__person{position:absolute;left:0;right:0;bottom:0;margin:0 auto;width:96%;height:auto;max-height:100%;object-fit:contain;object-position:bottom;-webkit-mask-image:linear-gradient(#000 86%,transparent);mask-image:linear-gradient(#000 86%,transparent);border-radius:0 0 var(--r-l) var(--r-l)}
.hero__pick{position:absolute;left:0;right:0;bottom:-34px;text-align:center;font-size:14px;color:var(--accent-d);font-weight:500;min-height:20px}
.sec{padding:clamp(80px,10vw,150px) 0}
.hero{min-height:0}
.hero__in,.promise__grid,.process__grid,.bill__grid,.faq__grid,.book__panel{grid-template-columns:1fr}
.hero__art{justify-self:center;max-width:480px;order:-1}
body{font-size:16px}
