:root{--ground:#E6E6E2; --paper:#F4F4F1; --ink:#121212; --mute:#55554F; --blue:#1F3FE0; --white:#FFFFFF; --line:rgba(18,18,18,.14); --line2:rgba(18,18,18,.28); --pad:clamp(20px,3.6vw,56px); --ease:cubic-bezier(.16,1,.3,1); --f:'Schibsted Grotesk',ui-sans-serif,system-ui,sans-serif; --m:'DM Mono',ui-monospace,monospace;}
