.lead{font-size:clamp(18px,1.35vw,20px);line-height:1.5;color:var(--mute);max-width:44ch}
.btn{display:inline-flex;align-items:center;justify-content:center;min-height:50px;padding:0 24px;border-radius:4px;font:550 16px/1 var(--f);text-decoration:none;border:1px solid transparent;cursor:pointer;transition:transform .25s var(--ease),background-color .25s,color .25s}
.btn:hover{transform:translateY(-2px)}
