:root{--bone:#E4E7E2; --ink:#121212; --acc:#FF6A13; --forest:#11463A; --white:#FFFFFF; --muted:#5E5850;--line:rgba(18,18,18,.16);--display:'Archivo',ui-sans-serif,system-ui,sans-serif;--body:'Hanken Grotesk',ui-sans-serif,system-ui,sans-serif;--pad:clamp(20px,4vw,56px); --max:1280px; --ease:cubic-bezier(.2,.7,.2,1);}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bone);color:var(--ink);font:400 17px/1.6 var(--body);-webkit-font-smoothing:antialiased;overflow-x:clip}
h1,h2,h3{font-family:var(--display);font-weight:900;font-stretch:125%;line-height:.95;letter-spacing:-.02em;margin:0;text-transform:uppercase}
h2{font-size:clamp(34px,5vw,72px)}
.wrap{width:100%;max-width:var(--max);margin:0 auto;padding:0 var(--pad)}
.btn{display:inline-flex;align-items:center;gap:10px;font:700 16px/1 var(--body);padding:17px 24px;border-radius:999px;text-decoration:none;border:2px solid var(--ink);transition:transform .18s var(--ease),background .2s,color .2s}
.btn:hover{transform:translateY(-2px)}
.btn:hover svg{transform:translateX(3px)}
.btn:active{transform:translateY(1px) scale(.98)}
.btn--acc{background:var(--acc);color:var(--ink)}
.btn--acc:hover{background:var(--ink);color:var(--white)}
.btn--ink{background:var(--ink);color:var(--white)}
.btn--ink:hover{background:var(--acc);color:var(--ink)}
.btn--line{background:transparent}
.btn--line:hover{background:var(--ink);color:var(--white)}
.btn--full{width:100%;justify-content:center}
.hero{min-height:calc(100svh - 118px);display:flex;align-items:center;padding:48px 0 64px;overflow:hidden}
.hero__in{display:grid;grid-template-columns:1.35fr .65fr;gap:clamp(24px,4vw,64px);align-items:center}
.hero__eyebrow{font-weight:700;font-size:14px;text-transform:uppercase;letter-spacing:.14em;margin-bottom:22px;color:var(--forest)}
.hero__cta{display:flex;flex-wrap:wrap;gap:12px}
.hero__art{position:relative;justify-self:center;width:min(100%,420px)}
.hero__funnel{width:100%;height:auto;overflow:visible;display:block}
.hero__shadow{fill:var(--acc);transform:translate(14px,14px)}
.hero__edge{fill:none;stroke:var(--ink);stroke-width:3;stroke-linejoin:round}
.hero__stages{list-style:none;padding:0;margin:0;position:absolute;right:-6%;bottom:2%;display:grid;gap:6px}
.hero__in{grid-template-columns:1.2fr .8fr}
.hero{min-height:auto}
.hero__in{grid-template-columns:1fr}
.hero__art{width:min(78%,360px);margin-top:24px}
body{font-size:16px}
.hero{padding:32px 0 56px}
.hero__stages{right:-14%}
html{scroll-behavior:auto}

:root{--bone:#EBE8E1; --ink:#121110; --panel:#1C1B19; --mute:#5F5B54; --line:#D3CEC3; --red:#E8361C; --redd:#C42A12; --fd:'Archivo',system-ui,sans-serif; --fb:'Geist',system-ui,sans-serif; --gut:clamp(20px,4vw,56px); --max:1320px; --ease:cubic-bezier(.16,1,.3,1);}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bone);color:var(--ink);font:400 17px/1.55 var(--fb);-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
h1,h2,h3{font-family:var(--fd);font-stretch:118%;font-weight:760;letter-spacing:-.03em;line-height:.98;margin:0;text-wrap:balance}
html{scrollbar-color:var(--mute) var(--bone)}
.wrap{max-width:var(--max);margin:0 auto;padding:0 var(--gut)}
.btn{--bg:var(--redd);display:inline-flex;align-items:center;gap:10px;min-height:48px;padding:0 22px;border-radius:999px;background:var(--bg);color:#fff;font:600 15px/1 var(--fb);text-decoration:none;border:1px solid transparent;cursor:pointer;transition:transform .3s var(--ease),background .3s}
.btn:hover{transform:translateY(-2px);--bg:#A92310}
.btn:hover svg{transform:translateX(3px)}
.btn:active{transform:translateY(0) scale(.98)}
.btn--sm{min-height:40px;padding:0 16px;font-size:14px}
.btn--line{--bg:transparent;color:var(--ink);border-color:var(--ink)}
.btn--line:hover{--bg:var(--ink);color:var(--bone)}
.hero{position:relative;background:var(--ink);color:var(--bone);min-height:calc(100svh - 110px);display:grid;grid-template-columns:minmax(0,.92fr) minmax(0,1.3fr);gap:clamp(24px,4vw,64px);align-items:center;padding:clamp(32px,6vh,72px) var(--gut) 96px;overflow:hidden}
.hero__lede{margin-top:26px;max-width:46ch;color:#C9C4BA;font-size:clamp(17px,1.3vw,19px)}
.hero__cta{display:flex;gap:24px;align-items:center;margin-top:34px;flex-wrap:wrap}
.hero{grid-template-columns:1fr;min-height:auto;padding-top:56px}
body{font-size:16px}
.hero{padding-bottom:84px}

:root{--paper:#EDEDE9; --ink:#121214; --mute:#5C5A55; --rule:#D3D3CD; --amber:#F2A33A; --night:#1B1A17; --ease:cubic-bezier(.16,1,.3,1); --f:'Familjen Grotesk',ui-sans-serif,system-ui,sans-serif; --m:'IBM Plex Mono',ui-monospace,monospace; --gut:clamp(20px,4vw,56px); --max:1320px;}
html{scroll-behavior:smooth;scroll-padding-top:84px;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--paper);color:var(--ink);font:400 17px/1.55 var(--f);-webkit-font-smoothing:antialiased;overflow-x:hidden}
.wrap{width:100%;max-width:calc(var(--max) + var(--gut)*2);margin:0 auto;padding:0 var(--gut)}
.h2{font-size:clamp(2.1rem,4.2vw,3.9rem);line-height:1.02;letter-spacing:-.035em;font-weight:600;margin:0;text-wrap:balance;max-width:16ch}
.btn{display:inline-flex;align-items:center;gap:10px;height:54px;padding:0 24px;border-radius:999px;font:600 16.5px/1 var(--f);text-decoration:none;transition:transform .25s var(--ease),background-color .25s,box-shadow .25s;will-change:transform}
.btn:hover{transform:translateY(-2px)}
.btn:active{transform:translateY(1px) scale(.98)}
.btn-amber{background:var(--amber);color:var(--ink);box-shadow:0 6px 16px -8px rgba(18,18,20,.35)}
.btn-amber:hover{background:#F6B353;box-shadow:0 12px 22px -10px rgba(18,18,20,.4)}
.btn-ghost{color:var(--paper);box-shadow:inset 0 0 0 1px rgba(242,239,232,.3)}
.btn-ghost:hover{box-shadow:inset 0 0 0 1px rgba(242,239,232,.8)}
.btn-lg{height:60px;padding:0 28px;font-size:17.5px}
.btn:hover .ico{transform:rotate(-8deg) scale(1.08)}
.hero{position:relative;min-height:calc(100svh - 110px);display:flex;flex-direction:column;justify-content:center;padding:40px 0 28px;overflow:hidden;isolation:isolate}
.hero-in{display:grid;grid-template-columns:minmax(0,1.02fr) minmax(0,1fr);gap:40px;align-items:center}
.h1{font-size:clamp(2.9rem,5.6vw,5.9rem);line-height:.96;letter-spacing:-.04em;font-weight:600;margin:0;text-wrap:balance;max-width:11.5ch}
.hero-act{margin-top:34px}
section{position:relative}
.hero-in{grid-template-columns:1fr 0.9fr}
.hero-copy{position:relative;z-index:2}
.hero{min-height:auto;padding:36px 0 24px}
.hero-in{grid-template-columns:1fr;gap:10px}
body{font-size:16.5px}
.h1{font-size:clamp(2.6rem,11.4vw,3.4rem)}
